#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import subprocess
import shutil
import sys

MARKER = "PATCH: Academy Roadmap bundle integrity repair v1"

FILES = {
    "controller": Path("academyControllers.js"),
    "repo": Path("backend/repositories/academySupabaseRepo.js"),
}

def read_source(path: Path):
    raw = path.read_bytes()
    bom = raw.startswith(b"\xef\xbb\xbf")
    if bom:
        raw = raw[3:]
    text = raw.decode("utf-8")
    newline = "\r\n" if b"\r\n" in raw else "\n"
    normalized = text.replace("\r\n", "\n")
    return normalized, newline, bom

def write_source(path: Path, text: str, newline: str, bom: bool):
    output = text.replace("\n", newline).encode("utf-8")
    if bom:
        output = b"\xef\xbb\xbf" + output
    path.write_bytes(output)

def replace_once(text: str, old: str, new: str, label: str):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(
            f"{label}: expected exactly 1 match, found {count}."
        )
    return text.replace(old, new, 1)

def check_node(path: Path):
    result = subprocess.run(
        ["node", "--check", str(path)],
        capture_output=True,
        text=True
    )
    if result.returncode != 0:
        detail = (result.stderr or result.stdout or "").strip()
        raise RuntimeError(
            f"node --check failed for {path}:\n{detail}"
        )

