        'async function persistRoadmapBundle(uid, profile = {}, plan = {}) {',
        "\n/* PATCH: Academy Roadmap bundle integrity repair v1 */\n\nfunction extractConcreteRoadmapMissionStepsV1(payload = {}) {\n    const safePayload =\n        payload && typeof payload === 'object'\n            ? payload\n            : {};\n\n    const roadmap =\n        safePayload.roadmap &&\n        typeof safePayload.roadmap === 'object'\n            ? safePayload.roadmap\n            : {};\n\n    const candidates = [];\n\n    [\n        safePayload.allMissions,\n        safePayload.roadmapSteps,\n        safePayload.steps,\n        safePayload.generatedMissions,\n        safePayload.todayMissions,\n        safePayload.missions,\n\n        roadmap.allMissions,\n        roadmap.roadmapSteps,\n        roadmap.steps,\n        roadmap.generatedMissions,\n        roadmap.missions\n    ].forEach((source) => {\n        if (!Array.isArray(source)) return;\n\n        source.forEach((item) => {\n            if (\n                item &&\n                typeof item === 'object'\n            ) {\n                candidates.push(item);\n            }\n        });\n    });\n\n    const seen = new Set();\n\n    return candidates\n        .map((step, index) =>\n            normalizeRoadmapStepForPersistence(\n                step,\n                index\n            )\n        )\n        .filter((step, index) => {\n            const identity =\n                sanitizeString(\n                    step.id ||\n                    step.title ||\n                    `roadmap-repair-step-${index + 1}`\n                )\n                    .toLowerCase();\n\n            if (\n                !identity ||\n                seen.has(identity)\n            ) {\n                return false;\n            }\n\n            seen.add(identity);\n            return true;\n        });\n}\n\nasync function repairRoadmapMissionBundleV1(\n    uid = '',\n    roadmapId = '',\n    payload = {}\n) {\n    const cleanUid =\n        sanitizeString(uid);\n\n    const cleanRoadmapId =\n        sanitizeString(roadmapId);\n\n    if (\n        !cleanUid ||\n        !cleanRoadmapId\n    ) {\n        return {\n            repaired: false,\n            roadmapReady: false,\n            missionCount: 0,\n            reason: 'missing_identity'\n        };\n    }\n\n    const roadmap =\n        await getRoadmapById(\n            cleanUid,\n            cleanRoadmapId\n        );\n\n    if (!roadmap) {\n        return {\n            repaired: false,\n            roadmapReady: false,\n            missionCount: 0,\n            reason: 'roadmap_not_found'\n        };\n    }\n\n    const existingMissions =\n        await listAllMissionsByRoadmap(\n            cleanUid,\n            cleanRoadmapId\n        );\n\n    if (existingMissions.length > 0) {\n        return {\n            repaired: false,\n            roadmapReady: true,\n            missionCount:\n                existingMissions.length,\n            missions:\n                existingMissions,\n            reason: 'already_ready'\n        };\n    }\n\n    const candidates =\n        extractConcreteRoadmapMissionStepsV1(\n            payload\n        );\n\n    if (!candidates.length) {\n        return {\n            repaired: false,\n            roadmapReady: false,\n            missionCount: 0,\n            reason: 'no_concrete_missions'\n        };\n    }\n\n    const now =\n        nowIso();\n\n    let createdCount = 0;\n\n    for (\n        let index = 0;\n        index < candidates.length;\n        index += 1\n    ) {\n        const mission =\n            candidates[index] || {};\n\n        const sourceMissionId =\n            sanitizeString(\n                mission.id ||\n                `step-${index + 1}`\n            );\n\n        const missionId =\n            (\n                'roadmap_repair_' +\n                cleanRoadmapId +\n                '_' +\n                sourceMissionId\n            )\n                .replace(\n                    /[^a-zA-Z0-9_-]+/g,\n                    '_'\n                )\n                .slice(0, 180);\n\n        const saved =\n            await upsertRecord(\n                'academyMissions',\n                cleanUid,\n                missionId,\n                {\n                    ...mission,\n                    id:\n                        missionId,\n                    sourceMissionId,\n                    roadmapId:\n                        cleanRoadmapId,\n                    status:\n                        sanitizeString(\n                            mission.status ||\n                            'pending'\n                        ),\n                    sortOrder:\n                        toNumber(\n                            mission.sortOrder,\n                            index + 1\n                        ),\n                    createdAt:\n                        mission.createdAt ||\n                        now,\n                    updatedAt:\n                        now,\n                    repairSource:\n                        'cached_roadmap_payload_v1'\n                },\n                {\n                    roadmapId:\n                        cleanRoadmapId,\n                    status:\n                        sanitizeString(\n                            mission.status ||\n                            'pending'\n                        ),\n                    insertOnly:\n                        true\n                }\n            );\n\n        if (saved) {\n            createdCount += 1;\n        }\n    }\n\n    const repairedMissions =\n        await listAllMissionsByRoadmap(\n            cleanUid,\n            cleanRoadmapId\n        );\n\n    return {\n        repaired:\n            createdCount > 0,\n        roadmapReady:\n            repairedMissions.length > 0,\n        missionCount:\n            repairedMissions.length,\n        missions:\n            repairedMissions,\n        createdCount,\n        reason:\n            repairedMissions.length > 0\n                ? 'cached_missions_restored'\n                : 'repair_write_empty'\n    };\n}\n\n/* END PATCH: Academy Roadmap bundle integrity repair v1 */\n\nasync function persistRoadmapBundle(uid, profile = {}, plan = {}) {",
        "academySupabaseRepo helper insertion"
